def retry_delay(attempt: int, base: float = 1.0, cap: float = 60.0) -> float:
    if attempt < 0 or base <= 0 or cap <= 0:
        raise ValueError("attempt must be nonnegative; base and cap must be positive")
    return min(base * (2 ** attempt), cap)
